def countInRange(nums, queries):
    n = len(nums)
    lo, hi = 0, n - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if nums[mid] < nums[mid + 1]:
            lo = mid + 1
        else:
            hi = mid
    peak = lo

    def at_most(x):
        a, b = 0, peak + 1
        while a < b:
            m = (a + b) // 2
            if nums[m] <= x:
                a = m + 1
            else:
                b = m
        left = a
        a, b = peak + 1, n
        while a < b:
            m = (a + b) // 2
            if nums[m] <= x:
                b = m
            else:
                a = m + 1
        return left + (n - a)

    return [at_most(h) - at_most(l - 1) for l, h in queries]
